[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en" class="dark">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <meta name="description" content="A global creative agency that challenges the status quo to create transformative experiences that win hearts and move markets in the eco-digital era." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet" />

  <style>
    /* ─── Design Tokens ─── */
    :root {
      --bg:          #0A0A0A;
      --bg-1:        #111111;
      --bg-2:        #181818;
      --bg-3:        #222222;
      --border:      rgba(255,255,255,0.08);
      --border-mid:  rgba(255,255,255,0.14);
      --text:        #FFFFFF;
      --text-2:      #A8A8A8;
      --text-3:      #6B6B6B;
      --accent:      #3B82F6;      /* electric blue */
      --accent-2:    #F59E0B;      /* warm amber */
      --accent-glow: rgba(59,130,246,0.18);
      --radius-sm:   4px;
      --radius:      8px;
      --radius-lg:   16px;
      --radius-xl:   24px;
      --ease:        cubic-bezier(0.16,1,0.3,1);
      --ease-out:    cubic-bezier(0,0,0.2,1);
      --t-fast:      150ms;
      --t-mid:       250ms;
      --t-slow:      400ms;
      --font:        'Inter', system-ui, -apple-system, sans-serif;
      --max-w:       1440px;
      --gutter:      clamp(1.25rem, 5vw, 5rem);
    }

    /* ─── Reset ─── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; color-scheme: dark; }
    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
      font-size: 16px;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }
    img { display: block; max-width: 100%; }
    a { color: inherit; text-decoration: none; }
    button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }
    ul, ol { list-style: none; }
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
    }

    /* ─── Skip link ─── */
    .skip-link {
      position: absolute; top: -100%; left: 1rem;
      background: var(--accent); color: #fff;
      padding: 0.5rem 1rem; border-radius: var(--radius);
      z-index: 9999; transition: top var(--t-fast);
    }
    .skip-link:focus { top: 1rem; }

    /* ─── Navigation ─── */
    .nav {
      position: fixed; top: 0; left: 0; right: 0;
      z-index: 1000;
      background: rgba(10,10,10,0.85);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border);
      transition: background var(--t-mid), border-color var(--t-mid);
    }
    .nav__inner {
      max-width: var(--max-w);
      margin: 0 auto;
      padding: 0 var(--gutter);
      height: 68px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 2rem;
    }
    .nav__logo {
      font-size: 1.25rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      white-space: nowrap;
      flex-shrink: 0;
    }
    .nav__logo span { color: var(--accent); }
    .nav__links {
      display: flex;
      align-items: center;
      gap: 0.25rem;
    }
    .nav__links a {
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--text-2);
      padding: 0.5rem 0.875rem;
      border-radius: var(--radius);
      transition: color var(--t-fast), background var(--t-fast);
    }
    .nav__links a:hover { color: var(--text); background: rgba(255,255,255,0.06); }
    .nav__links a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
    .nav__actions {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      flex-shrink: 0;
    }

    /* Language selector */
    .lang-selector { position: relative; }
    .lang-selector__btn {
      display: flex;
      align-items: center;
      gap: 0.4rem;
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--text-2);
      padding: 0.45rem 0.75rem;
      border-radius: var(--radius);
      border: 1px solid var(--border);
      background: transparent;
      transition: color var(--t-fast), border-color var(--t-fast), background var(--t-fast);
      cursor: pointer;
    }
    .lang-selector__btn:hover { color: var(--text); border-color: var(--border-mid); background: rgba(255,255,255,0.04); }
    .lang-selector__btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
    .lang-selector__btn svg { width: 14px; height: 14px; transition: transform var(--t-fast); }
    .lang-selector__btn[aria-expanded="true"] svg { transform: rotate(180deg); }
    .lang-selector__dropdown {
      display: none;
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      min-width: 160px;
      background: var(--bg-2);
      border: 1px solid var(--border-mid);
      border-radius: var(--radius-lg);
      padding: 0.5rem;
      box-shadow: 0 24px 48px rgba(0,0,0,0.6);
    }
    .lang-selector__dropdown.open { display: block; animation: fadeInDown var(--t-fast) var(--ease-out) both; }
    .lang-selector__dropdown a {
      display: flex; align-items: center; gap: 0.5rem;
      padding: 0.6rem 0.875rem;
      font-size: 0.875rem;
      color: var(--text-2);
      border-radius: var(--radius);
      transition: background var(--t-fast), color var(--t-fast);
    }
    .lang-selector__dropdown a:hover { background: rgba(255,255,255,0.06); color: var(--text); }
    .lang-selector__dropdown a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.625rem 1.25rem;
      border-radius: var(--radius);
      font-size: 0.875rem;
      font-weight: 600;
      transition: all var(--t-mid) var(--ease);
      cursor: pointer;
    }
    .btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
    .btn--primary {
      background: var(--text);
      color: var(--bg);
    }
    .btn--primary:hover { background: #D4D4D4; transform: translateY(-1px); }
    .btn--outline {
      border: 1px solid var(--border-mid);
      color: var(--text);
      background: transparent;
    }
    .btn--outline:hover { background: rgba(255,255,255,0.06); border-color: rgba(255,255,255,0.22); }
    .btn--accent {
      background: var(--accent);
      color: #fff;
    }
    .btn--accent:hover { background: #2563EB; transform: translateY(-1px); box-shadow: 0 8px 24px var(--accent-glow); }

    /* Hamburger */
    .nav__hamburger {
      display: none;
      flex-direction: column;
      justify-content: center;
      gap: 5px;
      width: 40px;
      height: 40px;
      padding: 8px;
      border-radius: var(--radius);
      border: 1px solid var(--border);
    }
    .nav__hamburger:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
    .nav__hamburger span {
      display: block;
      height: 1.5px;
      background: var(--text);
      border-radius: 2px;
      transition: transform var(--t-mid), opacity var(--t-fast);
    }
    .nav__hamburger.open span:nth-child(1) { transform: translateY(6.5px) rotate(45deg); }
    .nav__hamburger.open span:nth-child(2) { opacity: 0; }
    .nav__hamburger.open span:nth-child(3) { transform: translateY(-6.5px) rotate(-45deg); }

    /* Mobile nav */
    .nav__mobile {
      display: none;
      flex-direction: column;
      padding: 1rem var(--gutter) 1.5rem;
      border-top: 1px solid var(--border);
      gap: 0.25rem;
    }
    .nav__mobile.open { display: flex; }
    .nav__mobile a {
      display: block;
      padding: 0.75rem 0.875rem;
      color: var(--text-2);
      font-size: 1rem;
      font-weight: 500;
      border-radius: var(--radius);
      transition: background var(--t-fast), color var(--t-fast);
    }
    .nav__mobile a:hover { background: rgba(255,255,255,0.06); color: var(--text); }

    /* ─── Hero Carousel ─── */
    .hero {
      min-height: 100svh;
      padding-top: 68px;
      display: flex;
      flex-direction: column;
      position: relative;
      overflow: hidden;
    }
    .hero__carousel {
      flex: 1;
      position: relative;
    }
    .hero__slide {
      position: absolute;
      inset: 0;
      opacity: 0;
      pointer-events: none;
      transition: opacity var(--t-slow) var(--ease-out);
    }
    .hero__slide.active {
      opacity: 1;
      pointer-events: auto;
    }
    .hero__slide-bg {
      position: absolute;
      inset: 0;
      background-size: cover;
      background-position: center;
    }
    .hero__slide-bg::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(
        135deg,
        rgba(10,10,10,0.85) 0%,
        rgba(10,10,10,0.55) 50%,
        rgba(10,10,10,0.35) 100%
      );
    }
    .hero__slide-content {
      position: relative;
      z-index: 1;
      max-width: var(--max-w);
      margin: 0 auto;
      padding: 0 var(--gutter);
      height: 100%;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      padding-bottom: clamp(3rem, 8vh, 7rem);
    }
    .hero__label {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent-2);
      margin-bottom: 1.25rem;
    }
    .hero__label::before {
      content: '';
      display: inline-block;
      width: 24px;
      height: 1.5px;
      background: var(--accent-2);
    }
    .hero__title {
      font-size: clamp(2.25rem, 5.5vw, 5rem);
      font-weight: 800;
      letter-spacing: -0.04em;
      line-height: 1.06;
      max-width: 14em;
      margin-bottom: 1.25rem;
    }
    .hero__body {
      font-size: clamp(0.9375rem, 1.5vw, 1.125rem);
      color: rgba(255,255,255,0.7);
      max-width: 42em;
      line-height: 1.65;
      margin-bottom: 2.25rem;
    }
    .hero__cta { display: inline-flex; align-items: center; gap: 0.6rem; }

    /* Hero controls */
    .hero__controls {
      position: absolute;
      bottom: clamp(1.5rem, 4vh, 3rem);
      right: var(--gutter);
      z-index: 10;
      display: flex;
      align-items: center;
      gap: 0.75rem;
    }
    .hero__dots {
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .hero__dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: rgba(255,255,255,0.3);
      transition: background var(--t-fast), width var(--t-mid) var(--ease);
      cursor: pointer;
      border: none;
    }
    .hero__dot.active {
      width: 24px;
      border-radius: 3px;
      background: var(--text);
    }
    .hero__arrow {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.18);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--t-fast), border-color var(--t-fast);
      color: var(--text);
    }
    .hero__arrow:hover { background: rgba(255,255,255,0.18); }
    .hero__arrow:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
    .hero__arrow svg { width: 16px; height: 16px; }

    /* Slide backgrounds — color gradients as cinematic placeholders */
    .slide-bg-1 { background: linear-gradient(135deg, #0a0a14 0%, #0f1a3a 40%, #1a0a2e 100%); }
    .slide-bg-2 { background: linear-gradient(135deg, #0a1a14 0%, #0a2a1a 50%, #0a1a0a 100%); }
    .slide-bg-3 { background: linear-gradient(135deg, #1a0a0a 0%, #2a1014 50%, #1a0a0a 100%); }
    .slide-bg-4 { background: linear-gradient(135deg, #0a0a1a 0%, #101028 50%, #18102a 100%); }
    .slide-bg-5 { background: linear-gradient(135deg, #1a1000 0%, #2a1800 50%, #1a0e00 100%); }

    /* ─── Section utilities ─── */
    .section {
      padding: clamp(4rem, 10vh, 7rem) 0;
    }
    .section__inner {
      max-width: var(--max-w);
      margin: 0 auto;
      padding: 0 var(--gutter);
    }
    .section__header {
      margin-bottom: clamp(2.5rem, 5vw, 4rem);
    }
    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--text-3);
      margin-bottom: 1rem;
    }
    .eyebrow::before {
      content: '';
      display: inline-block;
      width: 20px;
      height: 1.5px;
      background: var(--text-3);
    }
    .section-title {
      font-size: clamp(1.75rem, 3.5vw, 3rem);
      font-weight: 800;
      letter-spacing: -0.04em;
      line-height: 1.1;
    }
    .section-sub {
      margin-top: 1rem;
      font-size: clamp(0.9375rem, 1.25vw, 1.0625rem);
      color: var(--text-2);
      max-width: 52em;
      line-height: 1.7;
    }
    .divider {
      height: 1px;
      background: var(--border);
    }

    /* ─── Team Carousel Section ─── */
    .team { background: var(--bg); }
    .team__region-tabs {
      display: flex;
      gap: 0;
      border-bottom: 1px solid var(--border);
      margin-bottom: 3rem;
      overflow-x: auto;
      scrollbar-width: none;
    }
    .team__region-tabs::-webkit-scrollbar { display: none; }
    .team__tab {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--text-3);
      padding: 0.875rem 1.5rem;
      border: none;
      background: none;
      position: relative;
      white-space: nowrap;
      transition: color var(--t-fast);
      cursor: pointer;
    }
    .team__tab::after {
      content: '';
      position: absolute;
      bottom: -1px;
      left: 0;
      right: 0;
      height: 2px;
      background: var(--text);
      transform: scaleX(0);
      transition: transform var(--t-mid) var(--ease);
    }
    .team__tab.active { color: var(--text); }
    .team__tab.active::after { transform: scaleX(1); }
    .team__tab:hover { color: var(--text-2); }
    .team__tab:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: var(--radius-sm); }

    .team__region { display: none; }
    .team__region.active { display: block; }

    /* Cards track */
    .team__track-wrapper { position: relative; }
    .team__track {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
      gap: 1.5rem;
    }
    .team__card {
      background: var(--bg-1);
      border: 1px solid var(--border);
      border-radius: var(--radius-xl);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      transition: border-color var(--t-mid), transform var(--t-mid) var(--ease);
    }
    .team__card:hover { border-color: var(--border-mid); transform: translateY(-4px); }
    .team__card-photo {
      aspect-ratio: 3/2;
      background: var(--bg-3);
      position: relative;
      overflow: hidden;
    }
    .team__card-photo img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    .team__card-photo-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .team__card-body {
      padding: 1.5rem;
      display: flex;
      flex-direction: column;
      flex: 1;
      gap: 1rem;
    }
    .team__card-meta {
      display: flex;
      flex-direction: column;
      gap: 0.25rem;
    }
    .team__card-name {
      font-size: 1rem;
      font-weight: 700;
      letter-spacing: -0.02em;
    }
    .team__card-title {
      font-size: 0.8125rem;
      color: var(--text-2);
    }
    .team__card-location {
      font-size: 0.75rem;
      color: var(--text-3);
      display: flex;
      align-items: center;
      gap: 0.35rem;
    }
    .team__card-location svg { width: 11px; height: 11px; flex-shrink: 0; }
    .team__card-quote {
      font-size: 0.875rem;
      color: var(--text-2);
      line-height: 1.65;
      flex: 1;
      font-style: italic;
    }
    .team__card-quote::before { content: '"'; }
    .team__card-quote::after { content: '"'; }
    .team__card-cta {
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--accent);
      display: flex;
      align-items: center;
      gap: 0.4rem;
      transition: gap var(--t-fast);
    }
    .team__card-cta:hover { gap: 0.65rem; }
    .team__card-cta:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: var(--radius-sm); }
    .team__card-cta svg { width: 14px; height: 14px; }

    /* ─── Work Showcase ─── */
    .work { background: var(--bg-1); }
    .work__scroll-wrapper {
      position: relative;
    }
    .work__track {
      display: flex;
      gap: 1.5rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
      padding-bottom: 1rem;
      -webkit-overflow-scrolling: touch;
    }
    .work__track::-webkit-scrollbar { display: none; }
    .work__card {
      flex: 0 0 clamp(280px, 38vw, 480px);
      scroll-snap-align: start;
      background: var(--bg-2);
      border: 1px solid var(--border);
      border-radius: var(--radius-xl);
      overflow: hidden;
      transition: border-color var(--t-mid), transform var(--t-mid) var(--ease);
      cursor: pointer;
    }
    .work__card:hover { border-color: var(--border-mid); transform: translateY(-4px); }
    .work__card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
    .work__card-thumb {
      aspect-ratio: 16/9;
      background: var(--bg-3);
      overflow: hidden;
      position: relative;
    }
    .work__card-thumb-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }
    .work__thumb-label {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 1.5rem;
      font-size: clamp(0.75rem, 1.5vw, 1rem);
      font-weight: 700;
      text-align: center;
      letter-spacing: -0.02em;
      line-height: 1.3;
    }
    .work__card-body { padding: 1.5rem; }
    .work__card-client {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--text-3);
      margin-bottom: 0.5rem;
    }
    .work__card-title {
      font-size: 1rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      line-height: 1.3;
      margin-bottom: 0.75rem;
    }
    .work__card-quote {
      font-size: 0.8125rem;
      color: var(--text-2);
      line-height: 1.6;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .work__card-attribution {
      margin-top: 0.75rem;
      font-size: 0.75rem;
      color: var(--text-3);
      font-style: italic;
    }
    .work__nav {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 0.5rem;
      margin-top: 2rem;
    }
    .work__arrow {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: var(--bg-2);
      border: 1px solid var(--border);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--t-fast), border-color var(--t-fast);
      color: var(--text);
    }
    .work__arrow:hover { background: rgba(255,255,255,0.08); border-color: var(--border-mid); }
    .work__arrow:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
    .work__arrow svg { width: 16px; height: 16px; }

    /* Work thumb color palettes */
    .wt-1 { background: linear-gradient(135deg, #0d2137 0%, #1a3a5c 100%); }
    .wt-2 { background: linear-gradient(135deg, #0d2b1e 0%, #1a4a30 100%); }
    .wt-3 { background: linear-gradient(135deg, #1e1e2e 0%, #2d2d4a 100%); }
    .wt-4 { background: linear-gradient(135deg, #2e1a0d 0%, #4a2d14 100%); }
    .wt-5 { background: linear-gradient(135deg, #1a0a1a 0%, #2e1030 100%); }
    .wt-6 { background: linear-gradient(135deg, #0d1a2e 0%, #1030 100%); }
    .wt-7 { background: linear-gradient(135deg, #1a1a0d 0%, #2a2a14 100%); }
    .wt-8 { background: linear-gradient(135deg, #1a0d0d 0%, #2e1414 100%); }

    /* ─── CTA Banner ─── */
    .cta-banner {
      background: var(--text);
      color: var(--bg);
      padding: clamp(3rem, 7vh, 6rem) 0;
    }
    .cta-banner__inner {
      max-width: var(--max-w);
      margin: 0 auto;
      padding: 0 var(--gutter);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 3rem;
      flex-wrap: wrap;
    }
    .cta-banner__title {
      font-size: clamp(2rem, 4vw, 3.5rem);
      font-weight: 800;
      letter-spacing: -0.04em;
      line-height: 1.05;
    }
    .cta-banner__body {
      font-size: 1rem;
      color: rgba(0,0,0,0.6);
      max-width: 45em;
      line-height: 1.7;
      margin-top: 0.875rem;
    }
    .cta-banner__left { flex: 1; min-width: min(280px, 100%); }
    .btn--dark {
      background: var(--bg);
      color: var(--text);
      padding: 0.875rem 2rem;
      font-size: 0.9375rem;
      border-radius: var(--radius);
    }
    .btn--dark:hover { background: #1a1a1a; transform: translateY(-1px); }

    /* ─── How We Work ─── */
    .how-we-work { background: var(--bg); }
    .how-we-work__layout {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: clamp(2rem, 5vw, 5rem);
      align-items: center;
    }
    .how-we-work__visual {
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, #0a1a2e 0%, #0e2840 50%, #1a3050 100%);
      border-radius: var(--radius-xl);
      border: 1px solid var(--border);
      overflow: hidden;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .how-we-work__visual-art {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .how-we-work__headline {
      font-size: clamp(2rem, 3.5vw, 3.25rem);
      font-weight: 800;
      letter-spacing: -0.04em;
      line-height: 1.08;
      margin-bottom: 1.25rem;
    }
    .how-we-work__body {
      font-size: clamp(0.9375rem, 1.2vw, 1rem);
      color: var(--text-2);
      line-height: 1.75;
      margin-bottom: 2rem;
    }

    /* ─── Latest Insights ─── */
    .insights { background: var(--bg-1); }
    .insights__grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 1.25rem;
    }
    .insights__card {
      background: var(--bg-2);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      transition: border-color var(--t-mid), transform var(--t-mid) var(--ease);
    }
    .insights__card:hover { border-color: var(--border-mid); transform: translateY(-3px); }
    .insights__card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
    .insights__card-thumb {
      aspect-ratio: 16/9;
      background: var(--bg-3);
      position: relative;
      overflow: hidden;
      flex-shrink: 0;
    }
    .insights__card-type {
      position: absolute;
      top: 0.75rem;
      left: 0.75rem;
      background: rgba(0,0,0,0.65);
      backdrop-filter: blur(8px);
      font-size: 0.6875rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      padding: 0.3rem 0.65rem;
      border-radius: var(--radius-sm);
      border: 1px solid rgba(255,255,255,0.12);
    }
    .insights__card-body {
      padding: 1.25rem;
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 0.875rem;
    }
    .insights__card-title {
      font-size: 0.9375rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      line-height: 1.35;
      flex: 1;
    }
    .insights__card-cta {
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--accent);
      display: flex;
      align-items: center;
      gap: 0.4rem;
      transition: gap var(--t-fast);
    }
    .insights__card-cta:hover { gap: 0.7rem; }
    .insights__card-cta svg { width: 13px; height: 13px; }
    .insights__card-link { display: contents; }
    .insights__card-link:focus-visible .insights__card { outline: 2px solid var(--accent); outline-offset: 2px; }

    /* Insight thumb gradients */
    .it-pod { background: linear-gradient(135deg, #0d0d2b 0%, #18183a 100%); }
    .it-art { background: linear-gradient(135deg, #0d1f0d 0%, #1a3018 100%); }
    .it-rpt { background: linear-gradient(135deg, #2b1a0d 0%, #3a2414 100%); }

    /* ─── Principles ─── */
    .principles { background: var(--bg); }
    .principles__grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1.5px;
      background: var(--border);
      border: 1px solid var(--border);
      border-radius: var(--radius-xl);
      overflow: hidden;
    }
    .principles__item {
      background: var(--bg);
      padding: clamp(2rem, 4vw, 3rem);
      transition: background var(--t-mid);
    }
    .principles__item:hover { background: var(--bg-1); }
    .principles__num {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.12em;
      color: var(--text-3);
      margin-bottom: 1.25rem;
    }
    .principles__title {
      font-size: clamp(1.125rem, 1.75vw, 1.375rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.2;
      margin-bottom: 0.875rem;
    }
    .principles__body {
      font-size: 0.9375rem;
      color: var(--text-2);
      line-height: 1.7;
    }

    /* ─── Footer ─── */
    .footer {
      background: var(--bg-1);
      border-top: 1px solid var(--border);
      padding: clamp(4rem, 8vh, 6rem) 0 0;
    }
    .footer__ctas {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.5px;
      background: var(--border);
      border: 1px solid var(--border);
      border-radius: var(--radius-xl);
      overflow: hidden;
      margin-bottom: 4rem;
    }
    .footer__cta-block {
      background: var(--bg-1);
      padding: clamp(2rem, 4vw, 3rem);
      display: flex;
      flex-direction: column;
      gap: 1.25rem;
      transition: background var(--t-mid);
    }
    .footer__cta-block:hover { background: var(--bg-2); }
    .footer__cta-body {
      font-size: 1rem;
      color: var(--text-2);
      line-height: 1.65;
      flex: 1;
    }
    .footer__links {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem 2rem;
      margin-bottom: 3rem;
    }
    .footer__links a {
      font-size: 0.875rem;
      color: var(--text-2);
      transition: color var(--t-fast);
    }
    .footer__links a:hover { color: var(--text); }
    .footer__links a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 2px; }
    .footer__bottom {
      border-top: 1px solid var(--border);
      padding: 1.5rem 0;
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      align-items: center;
      justify-content: space-between;
    }
    .footer__legal {
      font-size: 0.8125rem;
      color: var(--text-3);
      line-height: 1.6;
    }
    .footer__legal-links {
      display: flex;
      flex-wrap: wrap;
      gap: 0.25rem 1.25rem;
    }
    .footer__legal-links a {
      font-size: 0.8125rem;
      color: var(--text-3);
      transition: color var(--t-fast);
    }
    .footer__legal-links a:hover { color: var(--text-2); }

    /* ─── Cookie consent ─── */
    .cookie-banner {
      position: fixed;
      bottom: 1.5rem;
      left: 50%;
      transform: translateX(-50%);
      width: min(calc(100% - 3rem), 640px);
      background: var(--bg-2);
      border: 1px solid var(--border-mid);
      border-radius: var(--radius-xl);
      padding: 1.5rem;
      box-shadow: 0 24px 64px rgba(0,0,0,0.6);
      z-index: 2000;
      display: flex;
      flex-direction: column;
      gap: 1rem;
      animation: slideUp var(--t-slow) var(--ease-out) both;
    }
    .cookie-banner.hidden {
      display: none;
    }
    .cookie-banner__text {
      font-size: 0.875rem;
      color: var(--text-2);
      line-height: 1.6;
    }
    .cookie-banner__text a { color: var(--accent); text-decoration: underline; }
    .cookie-banner__actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.625rem;
      align-items: center;
    }
    .cookie-banner__btn {
      font-size: 0.8125rem;
      font-weight: 600;
      padding: 0.5rem 1rem;
      border-radius: var(--radius);
      transition: all var(--t-fast);
    }
    .cookie-banner__btn--accept {
      background: var(--text);
      color: var(--bg);
    }
    .cookie-banner__btn--accept:hover { background: #D4D4D4; }
    .cookie-banner__btn--decline {
      background: transparent;
      border: 1px solid var(--border-mid);
      color: var(--text-2);
    }
    .cookie-banner__btn--decline:hover { color: var(--text); border-color: rgba(255,255,255,0.22); }
    .cookie-banner__btn--settings {
      background: transparent;
      color: var(--text-3);
      text-decoration: underline;
      font-size: 0.8rem;
    }
    .cookie-banner__btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

    /* ─── Animations ─── */
    @keyframes fadeInDown {
      from { opacity: 0; transform: translateY(-8px); }
      to   { opacity: 1; transform: translateY(0); }
    }
    @keyframes slideUp {
      from { opacity: 0; transform: translateX(-50%) translateY(20px); }
      to   { opacity: 1; transform: translateX(-50%) translateY(0); }
    }
    @keyframes pulse-ring {
      0%   { transform: scale(0.9); opacity: 0.5; }
      50%  { transform: scale(1.05); opacity: 0.2; }
      100% { transform: scale(0.9); opacity: 0.5; }
    }

    /* ─── Responsive ─── */
    @media (max-width: 1024px) {
      .nav__links { display: none; }
      .nav__hamburger { display: flex; }
      .how-we-work__layout { grid-template-columns: 1fr; }
      .how-we-work__visual { max-width: 480px; }
    }
    @media (max-width: 768px) {
      .principles__grid { grid-template-columns: 1fr; }
      .footer__ctas { grid-template-columns: 1fr; }
      .team__track { grid-template-columns: 1fr; }
      .hero__controls { bottom: 1rem; }
    }
    @media (max-width: 480px) {
      .cta-banner__inner { flex-direction: column; gap: 1.5rem; }
      .insights__grid { grid-template-columns: 1fr; }
    }

    /* SVG icons utility */
    .icon { display: inline-block; flex-shrink: 0; }

    /* Visible focus for keyboard nav */
    :focus-visible {
      outline: 2px solid var(--accent);
      outline-offset: 2px;
    }
    /* Smooth card hover cursor */
    .work__card, .team__card, .insights__card { cursor: pointer; }
  </style>
</head>
